];
const schema = JSON.stringify({type:'object',properties:{phase:{type:'integer'},name:{type:'string'},classification:{type:'string',enum:['integrada','parcial','no integrada','no verificable']},evidence:{type:'array',items:{type:'string'}},visible:{type:'array',items:{type:'string'}},tests:{type:'array',items:{type:'string'}},gaps:{type:'array',items:{type:'string'}},confidence:{type:'string',enum:['alta','media','baja']}},required:['phase','name','classification','evidence','visible','tests','gaps','confidence']});
const results = await parallel('Auditoría de fases 1–18 de SmartResto', () => phases.map(p => agent(
  'Audita SOLO la FASE ' + p.n + ' (' + p.name + '). Alcance: ' + p.scope + '\n' +
  'Tarea: contrasta el plan maestro suministrado con el repositorio local actual en C:\\Users\\Nancy Sandoval\\Downloads\\SISRESTAURANTE\\RecomenRestaurant. Inspecciona código, plantillas, rutas Flask, pruebas y documentación de esta fase. No modifiques archivos, no ejecutes escrituras sobre BD ni servicios externos y no infieras integración solo porque exista una documentación.\n' +
  'Clasifica la fase como integrada solo si sus capacidades centrales están conectadas en backend/UI y respaldadas por evidencia; parcial si hay implementación significativa con brechas; no integrada si solo está planificada o no se halló código; no verificable si no puedes acceder a evidencia. Incluye rutas de archivos relativas y símbolos/rutas HTTP en evidence/visible, distingue UI observable de código no probado, identifica tests existentes sin afirmar que pasaron salvo que leas un resultado verificable. En gaps enumera brechas del alcance maestro (no generalidades). Devuelve SOLO el objeto JSON con la estructura común.',
  {brief:'Auditar fase ' + p.n + ': ' + p.name, schema, sandbox:'shared', effort_level:'standard', input_files:[{path:'C:\\Users\\Nancy Sandoval\\AppData\\Roaming\\Manus\\uploads\\QZWReduLc6acJZjR2ECiFT\\FyDTPn2KEoacQ0Cl2GE95K\\1-pasted_content_4.txt',name:'plan_maestro'}]}
  )), {schema});
const successful = results.filter(r => r.ok).map(r => r.value);
const failures = results.map((r,i) => r.ok ? null : {phase:phases[i].n,name:phases[i].name,code:r.error.code,message:r.error.message}).filter(Boolean);
return {phase_audits:successful,failures};

